// protogen uses the pinned pure-Go protobuf compiler and the official Go plugins.
// --check compares generated bytes without rewriting files, so CI catches contract drift.
package main

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"

	"github.com/bufbuild/protocompile"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protodesc"
	"google.golang.org/protobuf/types/descriptorpb"
	"google.golang.org/protobuf/types/pluginpb"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
func run() error {
	if len(os.Args) < 5 {
		return fmt.Errorf("usage: protogen source-root destination go-plugin grpc-plugin [--check]")
	}
	name := "peerscreen/media/v1/media.proto"
	compiler := protocompile.Compiler{Resolver: &protocompile.SourceResolver{ImportPaths: []string{os.Args[1]}}}
	files, err := compiler.Compile(context.Background(), name)
	if err != nil {
		return err
	}
	request := &pluginpb.CodeGeneratorRequest{FileToGenerate: []string{name}, Parameter: proto.String("paths=source_relative"), ProtoFile: []*descriptorpb.FileDescriptorProto{protodesc.ToFileDescriptorProto(files[0])}}
	data, err := proto.Marshal(request)
	if err != nil {
		return err
	}
	for _, plugin := range os.Args[3:5] {
		command := exec.Command(plugin)
		command.Stdin = bytes.NewReader(data)
		output, err := command.Output()
		if err != nil {
			return fmt.Errorf("protobuf plugin failed: %w", err)
		}
		response := &pluginpb.CodeGeneratorResponse{}
		if err = proto.Unmarshal(output, response); err != nil {
			return err
		}
		if response.GetError() != "" {
			return fmt.Errorf("protobuf generation: %s", response.GetError())
		}
		for _, file := range response.File {
			path := filepath.Join(os.Args[2], file.GetName())
			expected := []byte(file.GetContent())
			if len(os.Args) > 5 && os.Args[5] == "--check" {
				current, e := os.ReadFile(path)
				if e != nil || !bytes.Equal(current, expected) {
					return fmt.Errorf("generated contract changed: %s", file.GetName())
				}
			} else {
				if err = os.MkdirAll(filepath.Dir(path), 0755); err != nil {
					return err
				}
				if err = os.WriteFile(path, expected, 0644); err != nil {
					return err
				}
			}
		}
	}
	return nil
}
